const copy = new Map(uiCopy.map(row => [row[0], row]));
export function t(key: string | null | undefined, values: readonly (string | number)[] = [], language: UiLanguage = uiLanguage()) {
  if (!key) return '';
  const row = copy.get(key);
  const index = { pl: 0, en: 1, de: 2, uk: 3 }[language];
  return (row?.[index] ?? key).replace(/\{(\d+)\}/g, (_match, number) => String(values[Number(number)] ?? `{${number}}`));
}
